              setSearchQuery("");
              setUnderservedOnly(false);
            }}
          >
            Clear Filters
          </button>
        ) : null}
      </div>

      {canvasLoading && !canvas ? (
        <GhostOpportunityCards />
      ) : viewMode === "matrix" ? (
