import { useState } from "react";

import { useOnboarding } from "../onboarding/context";
import { useStudio } from "../state/StudioContext";
import type { StudioConfig } from "../types";
import { useUpdater } from "./updater/useUpdater";

export function SettingsPanel() {
  const {
    settings,
    saveSettings,
    displayName,
    setDisplayName,
    brief,
    openSetup,
    clearChat,
    refreshCanvas,
    llmHealth,
    mcpReachable,
    pushToast,
    connectors,
    presets,
    addConnector,
    deleteConnector,
  } = useStudio();
  const { enabled: tourEnabled, restart: restartTour } = useOnboarding();
  const [selectedPreset, setSelectedPreset] = useState("");
  const updater = useUpdater();

  function update<K extends keyof StudioConfig>(key: K, value: StudioConfig[K]): void {
    saveSettings({ ...settings, [key]: value });
  }

  const handleAddPreset = () => {
    if (!selectedPreset) {
      return;
    }
    void addConnector({ preset: selectedPreset });
    setSelectedPreset("");
  };

  return (
    <div className="settings">
      <div className="settings__context">
